def parse_pins(text):
    pins = {}
    for line in text.split('\n'):
        if line and not line.startswith('#'):
            name, version = line.split('==')
            pins[name] = version
    return pins

import math

def half_width(sd, n):
    return 1.96 * sd / math.sqrt(n)

ratio = half_width(2.0, 100_000) / half_width(2.0, 1_000)
